-- ============================================================================
-- 2026-10-15_0230 Time on site before Aug 20: Samsara's stay for 625 visits (the audit's v2 reading)
-- ============================================================================
-- THE ASK
--   Fred, 2026-10-14: "yes do both, use Samsara's time for the old ones"; 2026-10-15 on the audit: "For 3 that should
--   be get the whole stop", "For 7 the stay that most likely is the service", and trucks first, then re-measure
--   (2026-10-15_0045). The nightly recheck (edge fn time-on-site-samsara-recheck) covers visits from Aug 20, when our
--   truck stop table starts; this migration does the visits before it, from the audit's reading of Samsara.
-- HOW EACH VALUE WAS READ (samsara-checks/audit_2026-10-15/v2, outside the repos; scripts/checks/samsara_visit_audit.mjs)
--   For the truck on the visit NOW: Samsara's stays (gap between two trips) at the client's address (a trip ending at
--   its Samsara place, within 150 m of the place centre, or within 250 m of our map point) in the visit's window (date
--   -4 h to 10 AM next day ET). The job = the stay holding the completion (-5 / +15 min) plus the EARLIER stays less
--   than 15 min apart, never past a stay holding another visit's completion; with no stay holding it, the truck's only
--   visit to the address that day (went once). One stay -> that stay, whole even when another visit shares it
--   (decision 3); several (the truck moved during the job) -> the longest (decision 7).
--   Saved only where the truck went to the address ONCE in the window (one group of stays): 625 visits, of which
--   71 moved, 11 were blank, 42 went-once (no stay holding the completion). Left alone: visits
--   where it went there several separate times (they go on the review list), flagged visits, reviewed values, and
--   values within 2 min of Samsara's.
--   Cross-check: on the visits since Aug 20 the same reading and the nightly recheck agree on 49 of 53 changes.
-- WHAT CHANGES
--   actual_arrival_at / actual_departure_at / duration_minutes / time_on_site_source = 'samsara_stay', each guarded on
--   the duration and source read on 2026-10-15 (a visit changed since is skipped and the count fails), labelled
--   x-app-source time-on-site-samsara with a reason.
-- ROLLBACK: audit.logs.old_row for these visits (app_source time-on-site-samsara, 2026-10-15).
-- ============================================================================
BEGIN;
SET LOCAL lock_timeout = '3s';

DO $s$ DECLARE v_hdr text := current_setting('request.headers', true); n int; BEGIN
  PERFORM set_config('request.headers', (coalesce(nullif(v_hdr, '')::jsonb, '{}'::jsonb)
    || jsonb_build_object('x-app-source', 'time-on-site-samsara',
         'x-change-reason', 'Time on site set to Samsara''s own stay (2026-10-15 audit): the truck''s stay at the address in the visit''s window, whole when shared, the longest when the truck moved (Fred: "use Samsara''s time for the old ones", decisions 3 and 7).'))::text, true);
  UPDATE public.visits v
     SET actual_arrival_at = t.a, actual_departure_at = t.d,
         duration_minutes = round(extract(epoch FROM t.d - t.a) / 60)::integer, time_on_site_source = 'samsara_stay'
