     AND NOT EXISTS (SELECT 1 FROM public.visit_audit_flags f WHERE f.visit_id = v.id AND f.resolved_at IS NULL);
  GET DIAGNOSTICS n = row_count;
  PERFORM set_config('request.headers', coalesce(v_hdr, ''), true);
  IF n <> 625 THEN RAISE EXCEPTION 'expected 625 visits saved, got %', n; END IF;
