DO $v$ DECLARE r jsonb; BEGIN
  r := public.fn_time_on_site_checks();
  IF (r->>'T1')::int + (r->>'T2')::int + (r->>'T3')::int + (r->>'T4')::int + (r->>'T6')::int <> 0 THEN RAISE EXCEPTION 'VERIFY: checks %', r; END IF;
  -- Fred's hand-set values are untouched
  IF (SELECT count(*) FROM public.visits WHERE (id IN (3942, 5078) AND duration_minutes = 412) OR (id = 6498 AND duration_minutes = 34)) <> 3 THEN
    RAISE EXCEPTION 'VERIFY: a value Fred set (3942/5078/6498) moved'; END IF;
END $v$;

COMMIT;
